from dsl import *
o="외전당가"
trait("독손끝",o,"독 묻은 손끝","전투의 첫 합에서 주는 피해가 2할 늘고 회심의 일격 확률이 4푼 오른다. 독과 암기가 얽힌 사건에서 손끝이 먼저 안다.",T("first_strike",percent=20),T("crit",percent=4))
trait("약손길",o,"약 달이는 손","요양으로 되찾는 체력과 내력이 4할 늘어나고 상비약 회복이 2할 늘어난다. 병과 약이 얽힌 사건에서 다른 길이 열린다.",T("heal_rate",percent=40),T("consumable_rate",percent=20))
upgrade("당가침통",o,"당가의 침통","회심의 일격 확률이 단계마다 2푼 오르고 상비약 회복이 8푼 늘어난다.",T("crit",percent=2),T("consumable_rate",percent=8))
rnd("당가_흘러나온독",[2,3],"길에서 만난 가문의 독",
 "고갯길에 표국 수레가 멈춰 섰다. 표사 넷이 입술이 검게 죽어 누워 있다. 표두가 내 암기 주머니를 보고 멱살을 잡는다. \"당가의 독이다. 너희 것이야!\" 맞는 말이다. 표사의 손등에 박힌 침은 가문의 것이다. 다만 가문 사람이 쓴 것이 아니다. 침 끝이 무디게 갈려 있다. 누가 당가의 독을 사서 쓴 것이다.",
 [C("해독부터 하고, 독이 어디서 흘러나왔는지 캔다",O("넷 가운데 셋을 살렸다. 표두가 멱살을 놓았다. 침은 암장터에서 팔린 것이었다. 판 사람은 가문의 독고에서 일하던 하인이다. 가문에 전서를 띄웠다. 답장은 한 줄이었다. '알았다. 고맙다.'",alignment=AL(j=60),stats={"mind":5},fame=15)),
  C("해독해 주고 값을 받는다",O("표두는 이를 갈면서 전낭을 풀었다. 당가의 독은 당가만 푼다. 그것이 가문이 삼백 년을 버틴 까닭이다.",alignment=AL(s=50),silver=140,stats={"martial":2})),
  C("침을 뽑아 챙기고 떠난다",O("무딘 침이지만 독은 진짜다. 표두의 욕이 고개 아래까지 따라왔다. 넷이 어찌 되었는지는 모른다.",alignment=AL(m=60),stats={"martial":5})),
  C("맥만 짚고 그 자리에서 탕약을 지어 넷을 다 살린다",O("독은 풀 줄 알아도 상한 몸을 추스르는 것은 다른 일이다. 약왕곡에서 배운 대로 달였다. 넷이 다 일어났다. 표두가 무릎을 꿇으려는 것을 붙들었다.",alignment=AL(j=70),stats={"mind":6},fame=25),req={"trait":"약손길"},hidden=True)],origin=o)
rnd("당가_쫓겨난장인",[3,4],"쫓겨난 암기 장인",
 "산골 대장간의 풀무 소리가 귀에 익다. 가문의 암기를 벼리던 박자다. 모루 앞의 늙은이가 나를 보고 망치를 내려놓는다. 열다섯 해 전 독 없는 암기를 만들자고 했다가 가문에서 쫓겨난 장인이다. \"가주가 보냈느냐. 내 손목을 가지러.\" 모루 위에 처음 보는 꼴의 침이 놓여 있다.",
 [C("가문에는 알리지 않겠다고 한다",O("늙은이가 한참 나를 보다가 풀무를 다시 밟았다. \"네 동생 이야기는 들었다. 독을 푸는 데 쓰라고 만든 침이 있다. 가져가라.\" 가는 침 한 벌을 받았다. 독을 넣는 침이 아니라 빼는 침이다. 장인은 침에 바를 해독단 한 알도 얹어 주었다.",alignment=AL(j=50),stats={"mind":5},item="해독단")),
  C("가문에 알리고 상을 받는다",O("가문의 사람이 사흘 만에 왔다. 대장간은 비어 있었다. 모루 위에 침 하나가 박혀 있었을 뿐이다. 상은 받았다.",alignment=AL(s=50),silver=160)),
  C("새 암기의 벼리는 법을 내놓으라 한다",O("늙은이는 손목을 감싸 쥐고 불었다. 열다섯 해의 궁리가 반나절 만에 내 것이 되었다.",alignment=AL(m=60),stats={"martial":6},mastery=12)),
  C("모루 위의 침을 집어 무게와 결을 읽는다",O("손끝에 올려 보았다. 가문의 것보다 반 푼 가볍고, 날아가다 한 번 꺾인다. 늙은이의 눈이 커졌다. \"그걸 손끝으로 아는 놈이 가문에 남아 있었구나.\" 그가 벼린 것 가운데 가장 좋은 한 벌을 내주었다.",style_weapon=3,stats={"martial":4}),req={"trait":"독손끝"},hidden=True)],origin=o)

o="외전빙궁"
trait("빙하의숨",o,"얼음 밑의 숨","심법 회복이 1할 5푼 늘고 매달 내력을 5푼 더 회복한다. 추위와 고요가 얽힌 사건에서 흔들리지 않는다.",T("mindset_power",percent=15),T("turn_regen",hp_pct=0,qi_pct=5))
trait("적는눈",o,"적는 눈","사건과 기연에서 오르는 기량이 2할 5푼 늘어나고 무공 성취를 1할 더 빠르게 얻는다. 처음 보는 것을 놓치지 않는다.",T("event_growth",percent=25),T("mastery_rate",percent=10))
upgrade("빙백의결",o,"빙백의 결","받는 피해가 단계마다 1푼 줄고 심법 회복이 6푼 늘어난다.",T("damage_reduce",percent=1),T("mindset_power",percent=6))
rnd("빙궁_등불",[1,2],"등불의 밤",
 "정월 보름, 고을에 등이 걸렸다. 수천 개다. 강물에도 등이 떠내려간다. 궁에는 없는 것이다. 궁의 밤은 얼음에 비친 별뿐이다. 등 파는 아이가 종이등 하나를 내민다. \"소원을 적어서 띄우세요. 북쪽에서 오신 분도 소원은 있잖아요.\"",
 [C("등을 사서 궁의 사람들 이름을 적어 띄운다",O("궁주, 소궁주, 문지기 노인. 적다 보니 등이 모자랐다. 아이가 하나를 더 주었다. 책에 적었다. '남쪽 사람들은 바랄 것을 불에 실어 물에 보낸다.'",silver=-5,stats={"mind":5})),
  C("등이 얼마에 만들어져 얼마에 팔리는지 묻는다",O("종이와 대나무 값이 서 푼, 파는 값이 열 푼. 하룻밤에 고을 하나의 한 달 살림이 오간다. 책에 적었다. '남쪽에서는 소원도 장사다.'",alignment=AL(s=30),stats={"mind":4})),
  C("강물의 등을 장력으로 얼려 본다",O("등 스무 개가 얼음에 갇혀 섰다. 사람들이 비명을 질렀다. 불길한 징조라는 것이다. 얼음은 곧 깨 주었지만 그 고을에서는 다시 묵지 못했다.",alignment=AL(m=30),stats={"internal":5})),
  C("등 만드는 법을 처음부터 끝까지 보고 적는다",O("대를 쪼개고, 종이를 바르고, 초를 세운다. 등 장수 노인이 귀찮아하면서도 다 보여 주었다. 한 장을 다 채워 그렸다. 궁주께서 이 장을 보시면 무슨 말씀을 하실지 궁금하다.",stats={"mind":7},mastery=8),req={"trait":"적는눈"},hidden=True)],origin=o)
rnd("빙궁_눈고개",[3,4],"눈 고개의 상단",
 "때아닌 눈보라가 고개를 덮었다. 중원의 상단 하나가 눈에 갇혔다. 스무 명이 서로 끌어안고 굳어 간다. 남쪽 사람은 이 정도 추위에도 죽는다. 궁의 심법으로 한기를 뽑아 주면 살릴 수 있다. 다만 궁의 법은 심법을 밖에 보이지 말라 한다.",
 [C("법을 어기고 한기를 뽑아 준다",O("스무 명의 등에 차례로 손을 댔다. 한기가 내 경맥으로 몰려와 사흘을 앓았다. 상단 주인은 내가 무엇을 했는지 알지 못한 채 은자를 내밀었다. 받았다. 받지 않으면 묻는 말이 늘고, 궁의 법은 묻는 말을 싫어한다.",alignment=AL(j=70),stats={"internal":6},hp_pct=-20,fame=20)),
  C("불을 피우고 눈굴을 파는 법만 일러 준다",O("법은 어기지 않았다. 스무 명 가운데 열넷이 아침을 보았다. 책에 적었다. '여섯은 법이 죽였는지 눈이 죽였는지 모르겠다.'",stats={"mind":6})),
  C("살려 주는 값을 먼저 정한다",O("상단 주인은 굳은 입으로 고개를 끄덕였다. 짐의 절반이다. 스무 명이 다 살았고 궁의 겨울 창고가 찼다.",alignment=AL(s=60),silver=260,stats={"internal":3})),
  C("눈보라 속에 앉아 스무 명 몫의 한기를 한 번에 받아 낸다",O("얼음 밑의 숨으로 돌렸다. 한기는 독이 아니라 내 것이다. 스무 명의 입술에 핏기가 돌았고 나는 눈 속에서 오히려 더웠다. 상단의 아이가 내 소매를 잡고 놓지 않았다.",alignment=AL(j=70),stats={"internal":8},fame=25),req={"trait":"빙하의숨"},hidden=True)],origin=o)

o="외전매화"
trait("스승의이름",o,"스승의 이름","명성 60과 은자 40을 더 들고 시작한다. 스승의 이름을 아는 사람들이 먼저 말을 건다.",T("start_fame",amount=60),T("start_silver",amount=40))
trait("새벽수련",o,"새벽 수련","무공 성취를 2할 더 빠르게 얻고 회심의 일격 확률이 3푼 오른다. 수련이 얽힌 사건에서 몸이 먼저 깬다.",T("mastery_rate",percent=20),T("crit",percent=3))
upgrade("빈검집",o,"빈 검집","무공 성취를 단계마다 4푼 더 빠르게 얻고 회심의 일격 피해가 6푼 늘어난다.",T("mastery_rate",percent=4),T("crit_power",percent=6))
rnd("매화_사형의검",[2,3],"사형의 검을 찾는 사람",
 "객잔에 묵는데 중년의 여인이 찾아왔다. 스승의 첫째 제자, 내가 얼굴도 모르는 큰사형과 혼약했던 사람이라 한다. \"그이가 비무에 나가던 날 검을 두고 갔어요. 스승님께 맡긴다고. 돌아오면 찾으러 온다고.\" 스승의 초막 들보 위에 먼지 쌓인 검 한 자루가 있었다. 누구 것인지 묻지 못했던 검이다.",
 [C("초막으로 돌아가 검을 가져다준다",O("왕복 열흘 길이었다. 여인은 검을 안고 한참 서 있었다. \"스승님을 원망하지 않는다고 전해 주세요. 만나게 되면.\" 전할 말이 하나 늘었다.",alignment=AL(j=60),stats={"mind":6},flags=["매화_사형의말"])),
  C("큰사형이 어떤 사람이었는지 묻는다",O("웃음이 많았고, 스승 대신 도전을 받겠다고 먼저 나선 것도 그였다 한다. 스승이 말린 것을 뿌리치고. 스승이 왜 편지 한 장 없이 떠났는지 조금 더 알 것 같다.",stats={"mind":5,"martial":2})),
  C("검은 스승의 것이니 값을 치르라 한다",O("여인은 말없이 비녀를 뽑아 탁자에 놓았다. 받고 나서야 그것이 혼약의 예물이었음을 알았다. 물릴 수는 없었다.",alignment=AL(s=50),silver=90)),
  C("스승의 이름으로 사람을 보내 검을 실어 오게 한다",O("스승의 이름을 대자 표국이 삯을 반만 받고 나섰다. 나머지 반은 매화노검의 이야기 값이라 했다. 닷새 만에 검이 왔다. 여인은 검을 받고 스승이 좋아하던 차 한 봉지를 내밀었다. \"만나거든 달여 드리세요.\"",alignment=AL(j=50),stats={"mind":5},fame=10,flags=["매화_사형의말"]),req={"trait":"스승의이름"},hidden=True)],origin=o)
rnd("매화_정식도전",[3,4],"스승에게 온 도전장",
 "붉은 봉투의 도전장이 나를 찾아왔다. 받는 이는 매화노검 백송, 대신 받을 이는 그 제자. 보낸 사람은 서른도 안 된 창잡이다. 열째 자리를 노리는 자다. 객잔 마당에 구경꾼이 모였다. \"스승이 숨었으면 제자가 받는 것이 명부의 법이오. 당신 사형들도 그렇게 받았소.\"",
 [C("받는다",O("창끝이 내 소매를 찢었고, 내 초식은 그의 창대를 갈랐다. 그는 부러진 창을 들고 읍했다. 이긴 것은 나인데 스승이 왜 이것을 싫어했는지 알겠다. 다음 도전장이 벌써 문간에 와 있다.",battle="천하도전자",spar=True,foe="젊은 창잡이 위소",foe_line="\"백송의 자리는 비었고, 나는 그 앞에 섰소.\"",stats={"martial":6,"external":3},mastery=12,fame=25)),
  C("받지 않는다. 나는 명부의 사람이 아니다",O("구경꾼들이 야유했다. 창잡이는 침을 뱉고 떠났다. 스승도 이 야유를 들었을 것이다. 수백 번쯤.",stats={"mind":7})),
  C("이기면 도전자가 언젠가 내 사형들의 무덤을 찾아 술을 올린다는 조건을 건다",O("창잡이는 웃으며 받았고, 지고 나서 웃음을 거두었다. 무덤이 어디 있는지는 나도 아직 모른다. 그는 찾아서라도 가겠다고 했다. 약조를 지킬 자인지는 모르겠다.",battle="천하도전자",spar=True,foe="젊은 창잡이 위소",foe_line="\"무덤에 술을? 좋소. 질 일이 없으니.\"",alignment=AL(j=40),stats={"martial":6},fame=20)),
  C("밤새 수련한 몸 그대로 새벽 마당에서 받는다",O("그는 잠을 자고 나왔고 나는 자지 않았다. 몸이 이미 데워져 있었다. 세 수 만에 창이 그의 손을 떠났다. 구경꾼들은 아직 모이지도 않았다. 조용히 끝난 것이 마음에 든다.",battle="천하도전자",spar=True,foe="젊은 창잡이 위소",foe_line="\"새벽부터 받겠다니. 스승보다는 배짱이 좋군.\"",stats={"martial":8},mastery=18,fame=15),req={"trait":"새벽수련"},hidden=True)],origin=o)

o="외전살막"
trait("한칼버릇",o,"한 칼의 버릇","전투의 첫 합에서 주는 피해가 3할 늘어난다. 숨어들어 지우는 일에서 길을 안다.",T("first_strike",percent=30),T("crit",percent=5))
