rnd("살막_수레",[2,3],"젖먹이를 나르는 수레",
 "밤길에 포장 친 수레가 지나간다. 마부의 걸음이 살막의 걸음이다. 포장 안에서 젖먹이 우는 소리가 난다. 셋쯤 된다. 올해 살막이 사들인 아이들이다. 마부가 나를 알아보고 턱짓한다. \"수고한다. 너도 이 수레를 타고 왔지. 스무 해 전에.\"",
 [C("마부를 눕히고 수레를 빼돌린다",O("아이 셋을 강 건너 절에 맡겼다. 주지는 아무것도 묻지 않았다. 살막의 장부에는 올해 빈 줄이 셋 생길 것이다. 그리고 내 이름 옆에 표시가 하나 붙을 것이다.",battle="살막살수",foe="살막의 마부 노칠",foe_line="\"미쳤구나. 이건 막주의 물건이다.\"",alignment=AL(j=80),stats={"external":4,"martial":3},fame=10)),
  C("아이 하나의 패를 들여다보고 보낸다",O("삼백. 내 것과 같은 값이다. 스무 해 동안 값이 오르지 않았다. 수레는 어둠 속으로 갔다. 한참 서 있었다.",stats={"mind":6})),
  C("아이들을 파는 집이 어디인지 묻는다",O("\"흉년 든 고을이면 어디든.\" 마부는 순순히 일러 주었다. 그 고을들의 이름을 외웠다. 무엇에 쓸지는 아직 모른다.",alignment=AL(s=30),stats={"mind":4,"martial":2})),
  C("수레 뒤를 소리 없이 밟아 아이들이 가는 곳을 알아낸다",O("마부는 끝내 뒤를 돌아보지 않았다. 살막이 젖먹이를 기르는 곳은 산속의 빈 암자였다. 유모 넷, 아이 스물. 그 자리를 아는 살수는 이제 둘이다. 마부와 나.",stats={"martial":5,"mind":3},flags=["살막_암자"]),req={"trait":"죽은걸음"},hidden=True)],origin=o)
rnd("살막_제값",[3,4],"제 목숨 값을 낸 사람",
 "쪽지의 이름을 찾아가니 그는 술상을 차려 놓고 기다리고 있었다. 늙은 염상이다. \"앉게. 자네가 받은 쪽지는 내 조카가 낸 것일세. 재산이 탐나서. 값이 사백 냥이라지.\" 그가 탁자에 은자 궤를 올린다. \"팔백 냥일세. 내가 죽은 것으로 해 주게. 살막은 값을 더 낸 쪽 말을 듣는다 들었네.\"",
 [C("살막의 법대로 먼저 받은 일을 한다",O("살막은 값이 아니라 순서를 듣는다. 늙은이는 술잔을 든 채 고개를 끄덕였다. \"법이 있는 도적이로군.\" 패 뒷면의 숫자에서 사백을 뺐다.",alignment=AL(m=60),silver=150,stats={"martial":4})),
  C("팔백 냥을 받고 죽은 것으로 꾸민다",O("관 하나와 상여 하나. 늙은이는 그날 밤 배를 탔다. 조카는 재산을 받았고 살막은 사백 냥을 받았고 나는 팔백 냥을 받았다. 셈이 맞는 것은 나뿐이다.",alignment=AL(s=70),silver=300)),
  C("살막에 낼 몫만 받고 달아날 길을 열어 준다",O("궤에서 사백만 덜어 냈다. 살막에 낼 값이다. 나머지는 도로 밀었다. 늙은이가 오래 나를 보았다. \"살수가 왜.\" 답하지 않았다. 나도 모르기 때문이다.",alignment=AL(j=60),silver=150,stats={"mind":6})),
  C("조카의 방에 칼 한 자루를 꽂아 두고 일을 끝낸다",O("베개 옆에 꽂았다. 한 치 옆이다. 조카는 이튿날 쪽지를 거두어 달라고 살막에 웃돈을 냈다. 아무도 죽지 않았고 값은 두 번 들어왔다. 곡 노인이 처음으로 나를 칭찬했다.",alignment=AL(s=40),silver=260,stats={"martial":5}),req={"trait":"한칼버릇"},hidden=True)],origin=o)

o="외전수로"
trait("강바닥숨",o,"강바닥의 숨","받는 피해가 4푼 줄고 요양으로 되찾는 체력과 내력이 2할 늘어난다. 물이 얽힌 사건에서 물밑 길을 안다.",T("damage_reduce",percent=4),T("heal_rate",percent=20))
trait("채주핏줄",o,"채주의 핏줄","은자 80을 더 들고 시작하고 얻는 은자가 1할 5푼 늘어난다. 청교채의 옛 식구들이 먼저 알아본다.",T("start_silver",amount=80),T("silver_rate",percent=15))
upgrade("청교깃발",o,"청교채의 깃발","은자를 단계마다 30 더 들고 시작하고 받는 피해가 1푼 줄어든다.",T("start_silver",amount=30),T("damage_reduce",percent=1))
rnd("수로_소금배",[1,2],"밤물의 소금 배",
 "그믐밤, 불을 끈 배 세 척이 청교채의 옛 물목으로 든다. 소금 밀수선이다. 관의 눈을 피해 다니는 배라 통행세를 받아도 고발하지 못한다. 선주가 뱃전에서 낮게 묻는다. \"이 물목은 주인이 바뀌었다 들었소. 누구한테 삯을 내오?\"",
 [C("삯은 받되 예전 청교채의 값만 받는다",O("총채주가 받는 값의 삼분의 일이다. 선주는 귀를 의심하다가 은자를 세었다. \"청교채 채주가 살아 계셨소?\" 그 자식이라고만 했다. 이 물목으로 다니겠다는 배가 한 달 만에 열 척이 되었다.",alignment=AL(j=40),silver=70,fame=10)),
  C("삯을 받고 관선이 뜨는 날도 일러 준다",O("삯에 웃돈이 붙었다. 수채가 먹고사는 법이다.",alignment=AL(s=50),silver=140)),
  C("소금을 배째 빼앗는다",O("세 척의 소금이 수채의 밑천이 되었다. 선주는 헤엄쳐 달아나며 총채주에게 이르겠다고 소리쳤다. 이를 테면 이르라지.",alignment=AL(m=60),silver=260,stats={"external":3})),
  C("키잡이의 얼굴을 알아보고 이름을 부른다",O("청교채에서 노를 젓던 사내다. 그가 키를 놓고 뱃전에 엎드렸다. \"소채주!\" 선주는 그날로 삯 없이 지나갔고, 대신 밀수선들 사이에 말이 돌았다. 청교채의 핏줄이 물목에 돌아왔다고. 흩어졌던 식구 다섯이 그 말을 듣고 찾아왔다.",alignment=AL(j=40),stats={"mind":5},fame=20),req={"trait":"채주핏줄"},hidden=True)],origin=o)
rnd("수로_초관",[3,4],"수군 초관의 밀담",
 "나루 주막 뒷방에 수군의 젊은 초관이 평복으로 앉아 있다. \"천호가 총채주에게서 받는 은자를 나는 못 본 척하고 삽니다. 더는 못 하겠소. 총채주의 큰 배가 닻 내리는 날을 알려 주시오. 관선 열 척으로 치겠소. 물목은 당신이 가지시오.\" 아버지가 가라앉은 것도 관선의 불화살이었다.",
 [C("관의 손은 빌리지 않는다고 한다",O("초관은 한참 앉아 있다가 일어섰다. \"그럼 하나만 일러 주겠소. 천호가 다음에 태울 수채는 당신네요.\" 그 말 한마디가 관선 열 척보다 값졌다.",stats={"mind":6},flags=["수로_사공"])),
  C("손을 잡되 뱃사공과 피난선은 건드리지 않는다는 글을 받는다",O("초관은 글을 썼고 손도장을 찍었다. 관의 글이 얼마나 가는지는 두고 볼 일이다. 그래도 받아 둔 글은 쓸모가 있다.",alignment=AL(j=40),stats={"mind":5},fame=10)),
  C("손을 잡고 닻 내리는 날을 판다",O("초관은 은자까지 얹어 주었다. 관선이 총채주의 배 한 척을 태웠다. 큰 배는 아니었다. 총채주는 누가 팔았는지 알아내려 할 것이다.",alignment=AL(s=60),silver=220)),
  C("초관을 총채주에게 넘긴다",O("총채주의 사람이 초관을 끌고 갔다. 상으로 물목 하나를 받았다. 초관의 평복이 며칠 뒤 하류의 갈대밭에 걸렸다.",alignment=AL(m=70),silver=180,stats={"external":4})),
  C("관선이 묶인 포구에 물밑으로 들어가 밧줄의 매듭을 보고 온다",O("숨을 참고 열 척의 배 밑을 돌았다. 밧줄은 낡았고 키는 녹슬었다. 이 관선으로는 총채주의 큰 배를 못 잡는다. 초관에게 그대로 일러 주었다. 그는 얼굴이 하얘져서 돌아갔다. 헛되이 죽을 사람 여럿을 살린 셈이다.",stats={"mind":5,"external":4},flags=["수로_사공"]),req={"trait":"강바닥숨"},hidden=True)],origin=o)

o="외전혈승"
trait("피의경",o,"피로 외운 경","주는 피해가 3푼 늘고 심법 회복이 1할 늘어난다. 피와 경전이 얽힌 사건에서 구절이 먼저 떠오른다.",T("damage_bonus",percent=3),T("mindset_power",percent=10))
trait("탁발의발",o,"탁발의 발","기연을 만날 확률이 1할 5푼 오르고 매달 체력과 내력을 3푼씩 더 회복한다. 문전에서 쫓겨나는 일에 익숙하다.",T("fortune_rate",percent=15),T("turn_regen",hp_pct=3,qi_pct=3))
