rnd("혈승_염",[1,2],"염을 청하는 집",
 "산골 외딴집에서 노파가 죽었다. 절이 멀어 염해 줄 중이 없다. 아들이 잿빛 가사가 무엇인지도 모르고 내 소매를 잡는다. \"스님, 어머니 가시는 길에 경 한 줄만 읽어 주십시오.\" 혈교의 장례는 망자의 피를 거두어 교단에 바친다. 내가 아는 경은 그것뿐이다.",
 [C("피는 거두지 않고 아는 경을 읽는다",O("피의 경전에서 피가 나오지 않는 구절만 골라 읽었다. 몇 줄 되지 않았다. 아들은 그것이 무슨 경인지 모르고 절을 했다. 보리쌀 한 되를 받았다.",alignment=AL(j=50),stats={"mind":5})),
  C("경전대로 피를 거둔다",O("아들은 처음에는 놀랐지만 스님이 하시는 일이라며 물러섰다. 작은 병 하나가 찼다. 본산에 보낼 것이다. 노파의 피는 묽었다.",alignment=AL(m=60),stats={"internal":5})),
  C("경을 읽어 주고 넉넉히 받는다",O("아들은 소를 판 돈을 내놓았다. 경은 짧았고 값은 길었다.",alignment=AL(s=50),silver=80)),
  C("문전에서 듣던 다른 절의 염불을 흉내 내어 읽는다",O("탁발 다니며 수없이 쫓겨난 절들의 염불이다. 귀동냥으로 외운 것이 이럴 때 쓰였다. 아들은 울었고 나는 처음으로 피 냄새 없는 경을 끝까지 읽었다. 입안이 이상하게 달았다.",alignment=AL(j=60),stats={"mind":7}),req={"trait":"탁발의발"},hidden=True)],origin=o)
rnd("혈승_도반",[3,4],"달아나는 도반",
 "밤길 숲에서 잿빛 가사가 뛰쳐나와 내 발치에 엎어진다. 같은 해에 죽을 받아먹은 도반이다. 등에 채찍 자국이 선명하다. \"공양 고을에서 사발을 엎었어. 아이 것이었거든. 혈위대가 쫓아와. 나를 넘기든가, 숨기든가. 네가 정해.\" 숲 저편에서 횃불이 흔들린다.",
 [C("숲 깊이 숨기고 혈위대를 다른 길로 보낸다",O("혈위대주는 내 이마의 핏자국을 보고 길을 물었다. 조각을 품은 순례승의 말이다. 그들은 의심 없이 반대쪽으로 갔다. 도반은 새벽에 가사를 벗어 놓고 떠났다.",alignment=AL(j=70),stats={"mind":6},flags=["혈승_의심"])),
  C("넘긴다. 경전은 사발을 엎은 자를 용서하지 않는다",O("도반은 끌려가며 한 번 돌아보았다. 원망하는 눈이 아니었다. 그럴 줄 알았다는 눈이었다.",alignment=AL(m=70),stats={"internal":5,"external":3})),
  C("가진 것을 받고 눈을 감아 준다",O("도반은 바랑을 통째로 내밀었다. 은자 몇 냥과 염주 하나. 혈위대가 왔을 때 나는 아무것도 못 보았다고 했다.",alignment=AL(s=50),silver=60,stats={"mind":2})),
  C("혈위대 앞에서 경전의 구절을 들어 도반을 변호한다",O("'피는 스스로 내는 자의 것만 달다.' 셋째 권의 구절이다. 아이의 피는 아이가 낸 것이 아니니 엎은 것은 죄가 아니라고 했다. 혈위대주는 한참 입을 다물었다가 채찍을 거두었다. 구절을 그렇게 읽은 중은 처음이라 했다.",alignment=AL(j=60),stats={"mind":8},fame=10,flags=["혈승_의심"]),req={"trait":"피의경"},hidden=True)],origin=o)

o="외전야수"
trait("짐승의귀",o,"짐승의 귀","기연을 만날 확률이 1할 5푼, 달아날 확률이 1할 5푼 오른다. 산과 짐승이 얽힌 사건에서 뜻이 먼저 들린다.",T("fortune_rate",percent=15),T("flee_rate",percent=15))
